<template>
  <section class="protection-panel traffic-protection-panel">
    <a-spin :spinning="loading">
      <header class="workspace-head"><div><h2>OCIWorker流量保护</h2><p>监测当前租户全部实例及其全部VNIC，汇总本月估算出站流量。</p></div><div class="master"><span :class="config.enabled?'ok':'warn'">{{ config.enabled?'保护已开启':'保护已关闭' }}</span><button :class="['switch',{on:config.enabled}]" type="button" :disabled="switching||codeSending" @click="beginToggle(!config.enabled)"></button><button class="demo-btn primary" type="button" :disabled="codeSending" @click="beginConfigure">{{ codeSending?'正在发送验证码…':'配置流量保护' }}</button></div></header>
      <div class="stats"><article class="stat"><span>本月估算流量</span><strong>{{ bytesLabel(config.monthlyBytes) }}</strong></article><article class="stat"><span>保护额度</span><strong>{{ config.enabled?bytesLabel(config.monthlyLimitBytes):'未启用' }}</strong></article><article class="stat"><span>当前使用率</span><strong :class="config.enabled?'ok':'warn'">{{ config.enabled?`${usagePercent.toFixed(1)}%`:'仅保留历史' }}</strong></article><article class="stat"><span>下次采集</span><strong>{{ config.enabled?nextCollectLabel(config.nextCollectTime):'不会采集' }}</strong></article></div>
      <div class="usage"><div class="barline"><span>{{ instances.length }}台实例合计</span><span>{{ bytesLabel(config.monthlyBytes) }} / {{ bytesLabel(config.monthlyLimitBytes) }}</span></div><div class="bar"><i :style="{width:`${Math.min(100,usagePercent)}%`}"></i></div></div>
      <div v-if="instances.length" class="instances"><article v-for="(item,index) in instances" :key="item.instanceId" class="instance"><strong>{{ item.instanceName||item.instanceId }}</strong><span>{{ bytesLabel(item.bytesToNetwork) }}{{ index===0&&instances.length>1?' · 主要流量来源':'' }}</span></article></div>
      <div v-else-if="!loading" class="empty">暂无本月实例流量数据</div>
      <div class="info"><b>统计范围</b><span>当前租户{{ instances.length }}台实例全部纳入；一台实例有多个VNIC时会先汇总到实例，再汇总到租户。已删除实例本月产生的历史流量仍会保留。</span></div>
      <div class="info"><b>估算</b><span>VnicBytesToNetwork可能包含部分私网或Oracle服务通信，不能等同于最终计费流量。</span></div>
    </a-spin>

    <Teleport to="body"><div v-if="configVisible" class="overlay" @wheel.stop><section class="dialog traffic-protection-dialog" role="dialog" aria-modal="true" aria-labelledby="traffic-title"><header class="dialog-head"><div><h3 id="traffic-title">配置 OCIWorker 流量保护</h3><p>监控估算出站流量，达到阈值后告警或停止实例。</p></div><button class="x" type="button" :disabled="saving" @click="closeConfig">×</button></header><div class="dialog-body"><div class="note">这是OCIWorker自制保护，不会创建Oracle配额策略。流量基于实例VNIC发送指标估算，可能与Oracle最终计费流量存在差异。</div><div v-if="operationError" class="operation-error" role="alert"><strong>保存失败</strong><span>{{ operationError }}</span></div><div class="section"><div class="section-title"><i>TX</i><strong>月度流量保护</strong><em>OCIWorker</em></div><div class="rows">
      <div class="row"><div class="name"><strong>启用流量保护</strong><span>按实例汇总到当前租户</span></div><div class="control"><button :class="['switch',{on:form.enabled}]" type="button" @click="form.enabled=!form.enabled"></button><span class="value">{{ form.enabled?'已启用':'已关闭' }}</span></div><span class="state">{{ form.enabled?'监控中':'已关闭' }}</span></div>
      <div class="row"><div class="name"><strong>每月保护额度</strong><span>每月1日自动重置统计</span></div><div class="control"><input v-model.number="form.monthlyLimitTb" type="range" min="1" max="20"><span class="value">{{ form.monthlyLimitTb }} TB</span></div><span class="state">月度</span></div>
      <div class="row"><div class="name"><strong>Telegram预警</strong><span>达到额度百分比时发送预警</span></div><div class="control"><input v-model.number="form.warningPercent" type="range" min="50" max="95" step="5"><span class="value">{{ form.warningPercent }}%</span></div><span class="state">已启用</span></div>
      <div class="row"><div class="name"><strong>达到100%后</strong><span>再次实时复核，确认超限才执行</span></div><div class="control"><select v-model="form.exceedAction"><option value="STOP_ALL_RUNNING_INSTANCES">停止全部运行实例并发送TG通知</option><option value="ALERT_ONLY">仅发送紧急告警</option></select></div><span class="state risk">高风险</span></div>
      <div class="row"><div class="name"><strong>采集频率</strong><span>随额度使用率自动调整</span></div><div class="control"><span class="value frequency">低于80%：30分钟<br>80%～90%：15分钟<br>高于90%：5分钟</span></div><span class="state">自动</span></div>
    </div></div></div><footer class="dialog-foot"><span class="foot">保存后按当前设置执行监测和超限处理。</span><div class="actions"><button class="demo-btn" type="button" :disabled="saving" @click="closeConfig">取消</button><button class="demo-btn primary" type="button" :disabled="saving" @click="saveConfig">{{ saving?'正在保存…':saveLabel }}</button></div></footer></section></div></Teleport>

    <a-modal v-model:open="verifyVisible" :title="verifyTitle" :ok-text="pendingAction==='manage'?'继续':pendingAction==='disable'?'确认关闭':'确认开启'" :confirm-loading="saving||switching" :mask-closable="false" :closable="!saving&&!switching" :cancel-button-props="{ disabled: saving||switching }" :keyboard="false" @ok="submitVerifiedAction">
      <a-alert type="warning" show-icon message="验证码已发送至 Telegram" style="margin-bottom:12px" />
      <a-input v-model:value="verifyCode" maxlength="6" inputmode="numeric" placeholder="请输入 6 位 TG 验证码" size="large" @pressEnter="submitVerifiedAction" />
      <div class="verify-actions"><span>验证码有效期 5 分钟</span><a-button type="link" size="small" :loading="codeSending" @click="resendCode">重新发送</a-button></div>
    </a-modal>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { message } from 'ant-design-vue'
import { getTrafficProtectionOverview, saveTrafficProtection, setTrafficProtectionEnabled, unlockTrafficProtection } from '../../../api/tenant'
import { sendVerifyCode } from '../../../api/system'
const props=defineProps<{tenantId:string}>()
const loading=ref(false),saving=ref(false),switching=ref(false),codeSending=ref(false),configVisible=ref(false),verifyVisible=ref(false),usagePercent=ref(0),verifyCode=ref(''),verifyTitle=ref('安全验证'),accessToken=ref(''),resumeDraft=ref(false),operationError=ref('')
const pendingAction=ref<'manage'|'enable'|'disable'>('manage'),config=reactive<any>({enabled:false,monthlyBytes:0,monthlyLimitBytes:10*1024**4,warningPercent:80,exceedAction:'ALERT_ONLY'}),instances=ref<any[]>([])
const form=reactive({enabled:true,monthlyLimitTb:10,warningPercent:80,exceedAction:'STOP_ALL_RUNNING_INSTANCES'})
const saveLabel=computed(()=>form.enabled?(config.enabled?'保存':'启用'):'关闭')
function apply(data:any){Object.assign(config,data?.config||{});instances.value=(data?.instances||[]).slice().sort((a:any,b:any)=>Number(b.bytesToNetwork||0)-Number(a.bytesToNetwork||0));usagePercent.value=Number(data?.usagePercent||0)}
async function load(){loading.value=true;try{apply((await getTrafficProtectionOverview({id:props.tenantId})).data)}catch(e:any){message.error(e?.message||'读取流量保护状态失败')}finally{loading.value=false}}
function fillForm(){form.enabled=!!config.enabled;form.monthlyLimitTb=Math.min(20,Math.max(1,Math.round(Number(config.monthlyLimitBytes||0)/1024**4)));form.warningPercent=config.warningPercent||80;form.exceedAction=config.exceedAction||'ALERT_ONLY'}
async function requestCode(action:string,text:string){verifyCode.value='';await sendVerifyCode(action,{contextKey:props.tenantId,contextText:text});verifyVisible.value=true}
async function beginConfigure(){pendingAction.value='manage';verifyTitle.value='安全验证 — 配置流量保护';accessToken.value='';resumeDraft.value=false;operationError.value='';codeSending.value=true;try{await requestCode('trafficProtectionManage','配置流量保护')}catch(e:any){message.error(e?.message||'发送验证码失败')}finally{codeSending.value=false}}
async function beginToggle(value:boolean){pendingAction.value=value?'enable':'disable';verifyTitle.value=`安全验证 — ${value?'开启':'关闭'}流量保护`;codeSending.value=true;try{await requestCode(value?'trafficProtectionEnable':'trafficProtectionDisable',value?'开启流量保护':'关闭流量保护')}catch(e:any){message.error(e?.message||'发送验证码失败')}finally{codeSending.value=false}}
async function resendCode(){if(pendingAction.value==='manage'){await beginConfigure();return}await beginToggle(pendingAction.value==='enable')}
async function submitVerifiedAction(){if(!/^\d{6}$/.test(verifyCode.value)){message.warning('请输入 6 位 TG 验证码');return}try{if(pendingAction.value==='manage'){saving.value=true;const r=await unlockTrafficProtection({id:props.tenantId,verifyCode:verifyCode.value});accessToken.value=r.data?.accessToken||'';if(!accessToken.value)throw new Error('未获得操作授权');verifyVisible.value=false;if(!resumeDraft.value)fillForm();resumeDraft.value=false;configVisible.value=true}else{switching.value=true;apply((await setTrafficProtectionEnabled({id:props.tenantId,enabled:pendingAction.value==='enable',verifyCode:verifyCode.value})).data);verifyVisible.value=false;message.success(pendingAction.value==='enable'?'流量保护已开启':'流量保护已关闭')}}catch(e:any){if(pendingAction.value==='manage')accessToken.value='';message.error(e?.message||'操作失败')}finally{saving.value=false;switching.value=false}}
function closeConfig(){if(saving.value)return;configVisible.value=false;accessToken.value='';resumeDraft.value=false;operationError.value=''}
async function requestDraftReauthorization(){resumeDraft.value=true;pendingAction.value='manage';verifyTitle.value='安全验证 — 配置流量保护';configVisible.value=false;codeSending.value=true;try{await requestCode('trafficProtectionManage','配置流量保护')}catch(e:any){configVisible.value=true;message.error(e?.message||'发送验证码失败')}finally{codeSending.value=false}}
function authorizationFailed(text:string){return text.includes('授权已失效')||text.includes('授权已被使用')}
async function saveConfig(){if(!accessToken.value){message.warning('操作授权已失效，请重新验证');await requestDraftReauthorization();return}const wasEnabled=!!config.enabled;const willEnable=!!form.enabled;operationError.value='';saving.value=true;try{apply((await saveTrafficProtection({id:props.tenantId,enabled:form.enabled,monthlyLimitTb:form.monthlyLimitTb,warningPercent:form.warningPercent,exceedAction:form.exceedAction,accessToken:accessToken.value})).data);configVisible.value=false;accessToken.value='';message.success(!willEnable?'流量保护已关闭':wasEnabled?'流量保护配置已保存':'流量保护已启用')}catch(e:any){const text=e?.message||'保存流量保护失败';operationError.value=text;if(authorizationFailed(text))accessToken.value='';message.error(text)}finally{saving.value=false}}
function bytesLabel(v:any){let n=Number(v||0);const u=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return `${n.toFixed(i>=3?2:0)} ${u[i]}`}
function nextCollectLabel(v:any){if(!v)return '-';const ms=new Date(v).getTime()-Date.now();if(ms<=0)return '即将采集';const m=Math.max(1,Math.round(ms/60000));return `约${m}分钟后`}
onMounted(load)
</script>

